const items = $input.all();
const outcomes = items.map(i => i.json).filter(j => j && j.id);
const tenant_id = outcomes[0]?.tenant_id || 'default';
const total = outcomes.length;
const minSample = 5;
const nowIso = new Date().toISOString().slice(0, 10);

if (total < minSample) {
  const card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
    `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n\n` +
    `• <b>Amostra insuficiente na semana:</b> ${total} registros observados (Mínimo: ${minSample}).\n` +
    `• Nenhuma diretriz foi inferida para preservar a integridade das políticas.\n` +
    `• O motor continuará acumulando desfechos.`;
  return [{ json: { chat_id: 5281600644, text: card, insufficient: true, total, candidates: [] } }];
}

let accepted = 0;
let edited = 0;
let rejected = 0;
const patterns = {};

for (const o of outcomes) {
  if (o.outcome_type === 'ACEITO_INTEGRAL') accepted++;
  else if (o.outcome_type === 'EDITADO_POR_RAFAEL') {
    edited++;
    const key = `${o.domain || 'GERAL'}:${o.delta_analysis?.edit_type || 'MODIFICADO'}`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
  else if (o.outcome_type === 'RECUSADO_COM_MOTIVO') {
    rejected++;
    const key = `${o.domain || 'GERAL'}:REJEITADO`;
    patterns[key] = (patterns[key] || 0) + 1;
  }
}

const useful = accepted + edited;
const durPct = ((useful / total) * 100).toFixed(1);
const statusIcon = durPct >= 85.0 ? '🟢 <b>META BATIDA</b>' : '🟡 <b>ABAIXO DA META</b>';

function genUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const candidates = [];
for (const [key, count] of Object.entries(patterns)) {
  if (count >= 2) {
    const [dom, type] = key.split(':');
    const candidateId = genUuid();
    let rule = `Ajustar propostas em ${dom} conforme preferências de Rafael.`;
    let risk = 'LOW';
    if (type === 'MADE_MORE_CONCISE') rule = `Em ${dom}, gerar propostas mais concisas e diretas.`;
    else if (type === 'EXPANDED_DETAILS') rule = `Em ${dom}, detalhar os impactos operacionais antes do envio.`;
    else if (type === 'REJEITADO') {
      rule = `Em ${dom}, reavaliar ofertas e argumentos previamente recusados.`;
      risk = 'HIGH';
    }

    // Regra de autopromoção: baixo risco + count >= 2 => AUTO
    const isAuto = risk === 'LOW' && count >= 2;
    const promotion_mode = isAuto ? 'AUTO' : 'MANUAL_REVIEW';
    const status = isAuto ? 'PROMOTED' : 'CANDIDATE';
    const score = isAuto ? 0.880 : 0.650;
    const learning_run_id = `run-${candidateId.slice(0, 8)}`;
    const idempotency_key = `pk:${tenant_id}:${dom}:${candidateId.slice(0, 8)}`;

    candidates.push({
      id: candidateId,
      tenant_id,
      category: `APRENDIZADO_${dom}`,
      scope: 'INDICATOR',
      target_ref: dom,
      learned_rule: rule,
      confidence_score: 0.88,
      status,
      promotion_mode,
      promotion_policy_version: 'v2.3.0-controlled-autopromote',
      promotion_score: score,
      risk_level: risk,
      frequency: count,
      learning_run_id,
      idempotency_key
    });
  }
}

let card = `🧠 <b>Balanço Semanal de Aprendizado 360 (WF-104)</b>\n` +
  `📅 <i>Semana: ${nowIso}</i> | Tenant: <code>${tenant_id}</code>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n` +
  `📊 <b>Métricas de Assertividade da IA:</b>\n` +
  `• <b>Total de Propostas:</b> ${total}\n` +
  `• <b>Úteis / Aceitas:</b> ${useful} (${durPct}% de utilidade)\n` +
  `• <b>Ajustadas por Você:</b> ${edited}\n` +
  `• <b>Recusadas:</b> ${rejected}\n` +
  `• <b>Status da Meta (DUR ≥ 85%):</b> ${statusIcon}\n\n`;

const autoPromoted = candidates.filter(c => c.promotion_mode === 'AUTO');
const manualReview = candidates.filter(c => c.promotion_mode === 'MANUAL_REVIEW');

if (autoPromoted.length > 0) {
  card += `⚡ <b>Autopromovidas (Baixo Risco):</b>\n`;
  for (const c of autoPromoted) {
    card += `  ✓ <b>${c.learned_rule}</b> (Score: ${c.promotion_score})\n`;
  }
  card += `\n`;
}

if (manualReview.length > 0) {
  card += `🔍 <b>Revisões Solicitadas a Rafael (Alto Risco):</b>\n`;
  for (const c of manualReview) {
    card += `  • <code>/aprovardiretriz ${c.id}</code> — ${c.learned_rule}\n`;
  }
}

if (candidates.length === 0) {
  card += `💡 Nenhuma divergência recorrente detectada nesta semana. Sistema estável.\n`;
}

card += `━━━━━━━━━━━━━━━━━━━━━━━━━━\n<i>Diretrizes salvas no banco de dados com isolamento por tenant.</i>`;

return candidates.map(c => ({ json: { ...c, chat_id: 5281600644, text: card } }));
